#veo-bg {
  position: absolute;
  inset: 0;
  width: 1280px;
  height: 720px;
  object-fit: cover;
  opacity: 0.28;
  filter: blur(1.5px) saturate(1.2);
  z-index: 0;
}
#vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, transparent 40%, rgba(8,12,20,0.85) 100%);
  z-index: 1;
}
#vector-stage {
  position: absolute;
  inset: 0;
  z-index: 10;
}
